69	Future<List<Plugin>> findPlugins(FlutterProject project, { bool throwOnError = true}) async {
70	  final List<Plugin> plugins = <Plugin>[];
71	  final FileSystem fs = project.directory.fileSystem;
72	  final String packagesFile = fs.path.join(
73	    project.directory.path,
74	    '.packages',
75	  );
76	  final PackageConfig packageConfig = await loadPackageConfigWithLogging(
77	    fs.file(packagesFile),
78	    logger: globals.logger,
79	    throwOnError: throwOnError,
80	  );
81	  for (final Package package in packageConfig.packages) {
82	    final Uri packageRoot = package.packageUriRoot.resolve('..');
83	    final Plugin? plugin = _pluginFromPackage(
84	      package.name,
85	      packageRoot,
86	      project.manifest.dependencies,
87	      fileSystem: fs
88	    );
89	    if (plugin != null) {
90	      plugins.add(plugin);
91	    }
92	  }
93	  return plugins;
94	}
